        // a `.js` or a `.jsx` file, with `.js` taking precedence over `.jsx`
        // likewise for TS demos, with `.ts` taking precedence over `.tsx`
        const extensions =
          variant === 'JS' ? ['.js', '.jsx', '.ts', '.tsx'] : ['.ts', '.tsx', '.js', '.jsx'];
